variants.code_sketch:
interface Action { String run(Ctx ctx); }        // returns the next view id
Map<String, Action> flow = new HashMap<String, Action>();
flow.put("select", ctx -> { ctx.order.select(cart); return "amount"; });
flow.put("amount", ctx -> ctx.amountValid() ? "confirm" : "amount");
Action action = flow.get(ctx.step());
String view = action == null ? ctx.errorView() : action.run(ctx);
ctx.setStep(view);
